const norm = (s) => String(s || "").toLowerCase().normalize("NFKD").replace(/[^a-z0-9]/g, "");
const BY_NAME = new Map(Object.entries(BRAND_MARKS).map(([slug, [title]]) => [norm(title), slug]));

// Sites whose mark isn't simply their brand's name.
const SITE_SLUGS = {
  "youtube.com": "youtube", "youtu.be": "youtube", "reddit.com": "reddit", "wikipedia.org": "wikipedia", "quora.com": "quora",
  "medium.com": "medium", "x.com": "x", "twitter.com": "x", "facebook.com": "facebook", "instagram.com": "instagram",
  "gsmarena.com": "gsmarenadotcom", "flipkart.com": "flipkart", "tripadvisor.com": "tripadvisor", "tripadvisor.in": "tripadvisor",
  "yelp.com": "yelp", "airbnb.com": "airbnb", "ebay.com": "ebay", "walmart.com": "walmart", "target.com": "target",
  "mi.com": "xiaomi", "boat-lifestyle.com": "boat", "zomato.com": "zomato", "swiggy.com": "swiggy",
};

/** The Simple Icons slug for a brand name, or null. */
export function brandSlug(name) {
  return BY_NAME.get(norm(name)) || null;
}

/** The slug for a site: a known site, or a brand whose name is the site's own name (samsung.com, motorola.in). */
export function siteSlug(domain) {
  const d = String(domain || "").toLowerCase().replace(/^www\./, "");
  if (!d) return null;
  for (const [k, slug] of Object.entries(SITE_SLUGS)) if (d === k || d.endsWith("." + k)) return slug;
  const parts = d.split(".");
  const stem = parts.length > 2 && /^(co|com|net|org)$/.test(parts[parts.length - 2]) ? parts[parts.length - 3] : parts[parts.length - 2];
  return stem ? BY_NAME.get(norm(stem)) || null : null;
}

// Badge colours: muted, readable with white text in both themes.
const BADGE = ["#4F5BD5", "#0F766E", "#B45309", "#7C3AED", "#BE185D", "#0369A1", "#4D7C0F", "#9F1239", "#475569", "#C2410C"];

/** A letter badge for a name or site: the first letter (two for a leading digit) and a colour from the name. */
export function letterBadge(text) {
  const raw = String(text || "").trim().replace(/^www\./i, "");
  const parts = raw.split(".");
  const word = parts.length > 2 && /^(gadgets|hindi|m|in|en|blog|shop|store)$/i.test(parts[0]) ? parts[1] : parts[0];
  const letter = /^\d/.test(word) ? word.slice(0, 2) : (word[0] || "?").toUpperCase();
  let h = 0;
  for (const ch of raw.toLowerCase()) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return { letter, bg: BADGE[h % BADGE.length], fg: "#fff" };
}

// Light brand colours (Apple's black is fine; a yellow needs dark ink).
function inkOn(hex) {
  const n = parseInt(hex, 16);
  const l = (0.299 * (n >> 16) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) / 255;
  return l > 0.7 ? "#111" : "#fff";
}

/** SVG markup for a mark on its tile, or for a letter badge when there's no mark. */
export function markSvg({ slug, text }, size = 20) {
  const r = Math.round(size * 0.28);
  if (slug && BRAND_MARKS[slug]) {
    const [title, hex, d] = BRAND_MARKS[slug];
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="${size}" height="${size}" role="img" aria-label="${title.replace(/"/g, "")}"><rect width="32" height="32" rx="${r * 32 / size}" fill="#${hex}"/><g transform="translate(6.5 6.5) scale(.79)"><path fill="${inkOn(hex)}" d="${d}"/></g></svg>`;
  }
  const b = letterBadge(text);
  const fs = b.letter.length > 1 ? 13 : 16;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="${size}" height="${size}" aria-hidden="true"><rect width="32" height="32" rx="${r * 32 / size}" fill="${b.bg}"/><text x="16" y="${fs > 13 ? 21.5 : 20.5}" text-anchor="middle" font-family="Geist, system-ui, sans-serif" font-size="${fs}" font-weight="600" fill="${b.fg}">${b.letter.replace(/[<&]/g, "")}</text></svg>`;
}
